def frames(lines):
    results = []
    current_data = []

    for line in lines:
        if line == "":
            if current_data:
                results.append("\n".join(current_data))
            current_data = []
        elif line.startswith(":"):
            continue
        elif line.startswith("data:"):
            value = line[5:]
            if value.startswith(" "):
                value = value[1:]
            current_data.append(value)
        else:
            continue

    return results
