import json


def parse_jsonl(text):
    results = []
    for line_num, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            results.append(json.loads(line))
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON on line {line_num}")
    return results
