def flatten(value):
    """Flatten a nested dictionary with string keys into dot-separated keys.

    - Lists and scalar leaves are preserved as values.
    - An empty dictionary leaf is represented as {} at its path.
    - An empty root produces {}.
    - Does not mutate the input.
    """
    if not isinstance(value, dict):
        return value

    if len(value) == 0:
        return {}

    result = {}
    for key, val in value.items():
        if isinstance(val, dict):
            if len(val) == 0:
                result[key] = {}
            else:
                for subkey, subval in flatten(val).items():
                    result[f"{key}.{subkey}"] = subval
        else:
            result[key] = val
    return result
```

