def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Rules:
      - Must be absolute (start with '/'), otherwise ValueError.
      - Collapses repeated slashes.
      - Ignores '.' components.
      - Resolves '..' without going above root.
      - Returns '/' for root; never a trailing slash otherwise.
      - No filesystem access.
    """
    if not path.startswith("/"):
        raise ValueError(f"Expected an absolute path, got: {path!r}")

    stack: list[str] = []

    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # at root — silently ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

