import heapq


def order(deps):
    # Collect all nodes (keys and prerequisite-only nodes)
    nodes = set()
    for node, prereqs in deps.items():
        nodes.add(node)
        for p in prereqs:
            nodes.add(p)

    # Compute in-degree (number of prerequisites) and reverse adjacency
    in_degree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):  # deduplicate to handle repeated entries safely
            in_degree[node] += 1
            dependents[p].append(node)

    # Initialize min-heap with all nodes that have no prerequisites
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependency graph")

    return result
```

